<div class="d-flex flex-wrap justify-content-between mb-3 gap-2"><div><h4 class="mb-0"><?= e($t['tr_no']) ?> <?= badge($t['status']) ?></h4><div class="text-muted"><?= link_wh($t['from_warehouse_id'], $t['from_name']) ?> &rarr; <?= link_wh($t['to_warehouse_id'], $t['to_name']) ?></div></div>
<div class="d-flex gap-1 align-self-start no-print"><?php foreach ([['approved', 'Approve', 'success', 'inventory.transfers.approve', ['draft']], ['rejected', 'Reject', 'outline-danger', 'inventory.transfers.approve', ['draft']], ['dispatched', 'Dispatch', 'primary', 'inventory.transfers.dispatch', ['approved']], ['received', 'Receive', 'success', 'inventory.transfers.receive', ['dispatched']], ['cancelled', 'Cancel', 'outline-secondary', 'inventory.transfers.create', ['draft', 'approved']]] as [$to, $l, $c, $perm, $ok]):
 if (!Auth::can($perm) || !in_array($t['status'], $ok, true)) continue; ?><form method="post" action="<?= url('transfers/step') ?>" data-confirm="<?= e($l) ?> this transfer?"><?= csrf_field() ?><input type="hidden" name="id" value="<?= (int)$t['id'] ?>"><input type="hidden" name="to" value="<?= $to ?>"><button class="btn btn-<?= $c ?>"><?= $l ?></button></form><?php endforeach; ?><button class="btn btn-outline-secondary" onclick="window.print()"><i class="bi bi-printer"></i></button></div></div>
<div class="card"><table class="table table-sm mb-0"><thead class="table-light"><tr><th>SKU</th><th>Product</th><th class="text-end">Qty</th><th class="text-end">Received</th></tr></thead><tbody><?php foreach ($items as $i): ?><tr><td><?= e($i['sku']) ?></td><td><?= link_product($i['product_id'], $i['name']) ?></td><td class="text-end"><?= fq($i['qty']) ?></td><td class="text-end"><?= $i['received_qty'] !== null ? fq($i['received_qty']) : '' ?></td></tr><?php endforeach; ?></tbody></table></div>
<?php if ($t['status'] === 'dispatched'): ?><div class="alert alert-info mt-3 no-print">Stock has left the source warehouse and is in transit until the destination confirms receipt.</div><?php endif; ?>
